test "Inkling 2 HIP loop launch records cover the messages, the gates, their controls and the math probe on all served chips" {
    try std.testing.expectEqual(@as(usize, 27), records.len);
    try std.testing.expectEqual(@as(usize, 0), try hip_records.check(std.testing.allocator, &records, false));
}
